pub export fn median_two_array(a:[*c]const i64,len:usize)f64{const bad=-1.0e300;if(a==null or len<2 or len>259)return bad;if(a[0]<0 or a[1]<0 or a[0]+a[1]<1 or a[0]+a[1]>256 or len!=@as(usize,@intCast(a[0]+a[1]))+2)return bad;const n:usize=@intCast(a[0]+a[1]);const n1:usize=@intCast(a[0]);var v:[256]i64=undefined;for(0..n)|i|{v[i]=a[i+2];if(v[i]<-1000000 or v[i]>1000000)return bad;if(i<n1 and i>0 and v[i]<v[i-1])return bad;if(i>=n1 and i>n1 and v[i]<v[i-1])return bad;}for(1..n)|i|{const x=v[i];var j=i;while(j>0 and v[j-1]>x){v[j]=v[j-1];j-=1;}v[j]=x;}const m=n/2;return if(n%2==1) @floatFromInt(v[m]) else (@as(f64,@floatFromInt(v[m-1]))+@as(f64,@floatFromInt(v[m])))/2.0;}
